import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink, Router, ActivatedRoute } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ProductService } from '../../services/product.service';
import { CartService } from '../../services/cart.service';
import { AuthService } from '../../services/auth.service';
import { Product, Category } from '../../models/product.model';

@Component({
  selector: 'app-product-list',
  standalone: true,
  imports: [CommonModule, RouterLink, FormsModule],
  template: `
    <div class="container">
      <h2 class="text-center mt-4 mb-3">Our Products</h2>

      <!-- Filters -->
      <div class="filters mb-4">
        <select class="form-control" [(ngModel)]="selectedCategory" (change)="onFilterChange()">
          <option value="">All Categories</option>
          <option *ngFor="let cat of categories" [value]="cat.id">{{ cat.display_name }}</option>
        </select>

        <input 
          type="text" 
          class="form-control" 
          placeholder="Search products..." 
          [(ngModel)]="searchQuery"
          (input)="onSearch()"
        >
      </div>

      <!-- Products Grid -->
      <div class="grid" *ngIf="!loading">
        <div class="card" *ngFor="let product of products">
          <div [routerLink]="['/products', product.id]" style="cursor: pointer;">
            <img [src]="product.image" [alt]="product.name" class="card-img">
            <div class="card-body">
              <h3 class="card-title">{{ product.title }}</h3>
              <p class="card-text">{{ product.category_name }}</p>
              <div class="price-section">
                <span class="price-original" *ngIf="product.discounted_price">₹{{ product.price }}</span>
                <span class="price">₹{{ product.final_price }}</span>
                <span class="discount-badge" *ngIf="product.discount_percentage > 0">
                  {{ product.discount_percentage }}% OFF
                </span>
              </div>
              <p class="card-text">{{ product.purity }}</p>
              <span class="badge" [class.in-stock]="product.in_stock" [class.out-of-stock]="!product.in_stock">
                {{ product.in_stock ? 'In Stock' : 'Out of Stock' }}
              </span>
            </div>
          </div>
          <button
            class="btn btn-primary btn-block mt-2"
            (click)="addToCart(product, $event)"
            [disabled]="!product.in_stock"
          >
            Add to Cart
          </button>
        </div>
      </div>

      <div class="spinner" *ngIf="loading"></div>

      <p class="text-center mt-4" *ngIf="!loading && products.length === 0">
        No products found.
      </p>
    </div>
  `,
  styles: [`
    .filters {
      display: grid;
      grid-template-columns: 1fr 2fr;
      gap: 1rem;
    }

    .price-section {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin: 0.5rem 0;
    }

    .badge {
      display: inline-block;
      padding: 0.25rem 0.5rem;
      border-radius: 4px;
      font-size: 0.875rem;
    }

    .in-stock {
      background-color: #d4edda;
      color: #155724;
    }

    .out-of-stock {
      background-color: #f8d7da;
      color: #721c24;
    }

    @media (max-width: 768px) {
      .filters {
        grid-template-columns: 1fr;
      }
    }
  `]
})
export class ProductListComponent implements OnInit {
  products: Product[] = [];
  categories: Category[] = [];
  selectedCategory = '';
  searchQuery = '';
  loading = false;

  constructor(
    private productService: ProductService,
    private route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    this.loadCategories();

    // Check for category query param
    this.route.queryParams.subscribe(params => {
      if (params['category']) {
        this.selectedCategory = params['category'];
      }
      this.loadProducts();
    });
  }

  loadCategories(): void {
    this.productService.getCategories().subscribe({
      next: (data: any) => {
        // Handle both array and paginated response
        this.categories = Array.isArray(data) ? data : (data.results || []);
        console.log('Categories loaded:', this.categories.length);
      },
      error: (err) => console.error('Error loading categories:', err)
    });
  }

  loadProducts(): void {
    this.loading = true;
    const params: any = {};

    if (this.selectedCategory) {
      params.category = this.selectedCategory;
    }

    this.productService.getProducts(params).subscribe({
      next: (data) => {
        this.products = data.results;
        this.loading = false;
      },
      error: (err) => {
        console.error('Error loading products:', err);
        this.loading = false;
      }
    });
  }

  onFilterChange(): void {
    this.loadProducts();
  }

  onSearch(): void {
    if (this.searchQuery.length > 2) {
      this.loading = true;
      this.productService.searchProducts(this.searchQuery).subscribe({
        next: (data) => {
          this.products = data;
          this.loading = false;
        },
        error: (err) => {
          console.error('Error searching products:', err);
          this.loading = false;
        }
      });
    } else if (this.searchQuery.length === 0) {
      this.loadProducts();
    }
  }
}

